// CS × 数学技能树 — page logic. Data comes from data.js (window.SKILLTREE, generated by scripts/build.mjs).
// Pan/zoom uses @panzoom/panzoom (vendor/). Everything else here is plain DOM code.
(() => {
  "use strict";

  const D = window.SKILLTREE;
  const SK = new Map(D.skills.map((s) => [s.id, s]));
  const LANE = new Map(D.lanes.map((l) => [l.id, l]));
  const { w: CW, h: CH, colW: COLW } = D.meta.card;
  const STORE = "cs-math-skilltree/v1";
  const TOP = 48; // room for step labels
  const LANE_HEAD = 44;
  const LANE_GAP = 18;
  const LANE_PAD_X = 16;

  const $ = (sel, root = document) => root.querySelector(sel);
  const el = (tag, attrs = {}, ...kids) => {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k === "class") n.className = v;
      else if (k === "html") n.innerHTML = v;
      else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v === true ? "" : v);
    }
    for (const kid of kids.flat()) if (kid != null) n.append(kid.nodeType ? kid : document.createTextNode(kid));
    return n;
  };
  const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  const ICON = {
    lit: '<svg viewBox="0 0 16 16"><path d="M3 8.5l3.2 3L13 4.5"/></svg>',
    avail: '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="5.5"/><path d="M8 5.5v5M5.5 8h5"/></svg>',
    locked: '<svg viewBox="0 0 16 16"><rect x="3.5" y="7" width="9" height="6.5" rx="1"/><path d="M5.5 7V5.2a2.5 2.5 0 015 0V7"/></svg>',
  };
  const STATE_TEXT = { lit: "已点亮", avail: "现在能学", locked: "未解锁" };
  const TIER_TEXT = { website: "学习网站", material: "讲义 / 资料", book: "教材", course: "课程", video: "视频课程" };

  // ── persisted state ───────────────────────────────────────────────
  const state = { learned: new Set(), collapsed: new Set(["X"]), goal: [], goalLabel: "", introSeen: false, legacyProgress: null };
  let progressRevised = false;
  function readProgress(data) {
    const old = new Set(data.learned || []);
    const learned = new Set([...old].filter(id => SK.has(id)));
    if ((data.version || 1) < 2) {
      for (const [from, to] of Object.entries(D.progressMerges || {})) {
        // One completed component does not establish completion of the expanded skill.
        if (learned.has(to) && !old.has(from)) learned.delete(to);
      }
    }
    return learned;
  }
  try {
    const saved = JSON.parse(localStorage.getItem(STORE) || "null");
    if (saved) {
      state.learned = readProgress(saved);
      progressRevised = (saved.learned || []).some(id => !state.learned.has(id));
      state.legacyProgress = saved.legacyProgress || (progressRevised ? { learned: saved.learned || [], goal: saved.goal || [] } : null);
      if (saved.collapsed) state.collapsed = new Set(saved.collapsed);
      state.goal = [...new Set((saved.goal || []).map(id => D.progressMerges?.[id] || id).filter(id => SK.has(id)))];
      state.goalLabel = saved.goalLabel || "";
      state.introSeen = !!saved.introSeen;
    }
  } catch { /* private mode or blocked storage: start fresh */ }
  function save() {
    try {
      localStorage.setItem(STORE, JSON.stringify({
        version: 2, legacyProgress: state.legacyProgress, learned: [...state.learned], collapsed: [...state.collapsed], goal: state.goal,
        goalLabel: state.goalLabel, introSeen: state.introSeen,
      }));
    } catch { /* ignore */ }
  }
  // Keep the invariant "a lit skill has all required prerequisites lit" even for imported/old data.
  function normalizeLearned() {
    let changed = true;
    while (changed) {
      changed = false;
      for (const id of state.learned) {
        if (SK.get(id).required.some((r) => !state.learned.has(r.id))) { state.learned.delete(id); changed = true; }
      }
    }
  }
  normalizeLearned();

  // ── graph helpers ─────────────────────────────────────────────────
  const status = (id) => state.learned.has(id) ? "lit" : SK.get(id).required.every((r) => state.learned.has(r.id)) ? "avail" : "locked";
  function ancestors(id, out = new Set()) {
    for (const r of SK.get(id).required) if (!out.has(r.id)) { out.add(r.id); ancestors(r.id, out); }
    return out;
  }
  function dependents(id, out = new Set()) {
    for (const d of SK.get(id).unlocks) if (!out.has(d)) { out.add(d); dependents(d, out); }
    return out;
  }
  const byStep = (a, b) => SK.get(a).step - SK.get(b).step || SK.get(b).reach - SK.get(a).reach || a.localeCompare(b);
  // Skills still to learn for a goal, in an order that respects every required edge.
  function planFor(goalIds) {
    const need = new Set();
    for (const g of goalIds) { need.add(g); ancestors(g, need); }
    return [...need].sort(byStep);
  }

  // ── map construction ──────────────────────────────────────────────
  const mapEl = $("#map");
  const lanesEl = $("#lanes");
  const cardsEl = $("#cards");
  const colsEl = $("#cols");
  const svg = $("#edges");
  const gBase = $("#edges-base");
  const gFocus = $("#edges-focus");
  const cards = new Map();
  const laneEls = new Map();
  const laneTop = new Map();
  let selected = null;
  let mapW = 0;
  let mapH = 0;

  const steps = D.meta.steps;
  mapW = (steps - 1) * COLW + CW + LANE_PAD_X;
  for (let i = 1; i <= steps; i++) {
    const x = (i - 1) * COLW;
    colsEl.append(el("div", { class: "col-label", style: `left:${x}px` },
      `第 ${i} 步`, i === 1 ? el("span", { class: "start" }, "· 无必须前置，从这里开始") : null));
    colsEl.append(el("div", { class: "col-guide", style: `left:${x + CW / 2}px` }));
  }

  for (const lane of D.lanes) {
    const prog = el("span", { class: "lane-prog" });
    const head = el("button", { class: "lane-head", "aria-expanded": "true", onclick: (e) => { e.stopPropagation(); toggleLane(lane.id); } },
      el("span", { class: "swatch" }),
      el("span", { class: "lane-name" }, lane.name),
      el("span", { class: "lane-en", lang: "en" }, lane.en),
      lane.optional ? el("span", { class: "lane-tag" }, "选修") : null,
      prog,
      el("span", { class: "chev", "aria-hidden": "true" }, "▾"));
    const box = el("div", { class: "lane", style: `--dc:${lane.color}` }, head);
    box._prog = prog;
    box._head = head;
    laneEls.set(lane.id, box);
    lanesEl.append(box);
  }

  for (const s of D.skills) {
    const lane = LANE.get(s.lane);
    const c = el("button", {
      class: "card" + (s.optional ? " opt" : ""),
      style: `--dc:${lane.color};width:${CW}px;height:${CH}px`,
      "data-id": s.id,
      title: s.guide ? `${s.desc}\n双击打开知识导览图` : s.desc,
    },
    el("span", { class: "c-ico", "aria-hidden": "true" }),
    el("span", { class: "c-text" }, el("span", { class: "c-name" }, s.name), el("span", { class: "c-en", lang: "en" }, s.en)),
    el("span", { class: "c-lv", "aria-hidden": "true" }, `D${s.entry}`));
    // Prerequisites from other lanes are not drawn until the card is selected (they would cross every lane);
    // a stub with one dot per source lane says they exist.
    const ext = s.required.filter((r) => SK.get(r.id).lane !== s.lane);
    if (ext.length) {
      const from = [...new Set(ext.map((r) => SK.get(r.id).lane))];
      c.append(el("span", {
        class: "c-ext", "aria-hidden": "true",
        title: `还要用到其他领域的必须前置：${ext.map((r) => `${SK.get(r.id).name}（${LANE.get(SK.get(r.id).lane).short}）`).join("、")}`,
      }, from.slice(0, 3).map((l) => el("i", { style: `background:${LANE.get(l).color}` }))));
    }
    c.addEventListener("click", (e) => { if (!dragMoved) select(s.id); e.stopPropagation(); });
    c.addEventListener("dblclick", (e) => { if (!dragMoved) Guide.open(s.id); e.stopPropagation(); });
    c.addEventListener("focus", () => ensureVisible(s.id));
    cards.set(s.id, c);
    cardsEl.append(c);
  }

  function toggleLane(id) {
    if (state.collapsed.has(id)) state.collapsed.delete(id); else state.collapsed.add(id);
    save();
    layout();
  }

  function layout() {
    const keep = typeof pz !== "undefined" ? screenOf(0, 0) : null;
    let y = TOP;
    for (const lane of D.lanes) {
      const box = laneEls.get(lane.id);
      const collapsed = state.collapsed.has(lane.id);
      const h = collapsed ? LANE_HEAD : LANE_HEAD + lane.height;
      box.classList.toggle("collapsed", collapsed);
      box._head.setAttribute("aria-expanded", String(!collapsed));
      Object.assign(box.style, { top: `${y}px`, height: `${h}px`, width: `${mapW + LANE_PAD_X}px` });
      laneTop.set(lane.id, y);
      y += h + LANE_GAP;
    }
    mapH = y;
    for (const s of D.skills) {
      const c = cards.get(s.id);
      c.hidden = state.collapsed.has(s.lane);
      c.style.left = `${s.x}px`;
      c.style.top = `${laneTop.get(s.lane) + LANE_HEAD + s.y}px`;
    }
    for (const g of colsEl.querySelectorAll(".col-guide")) g.style.height = `${mapH - TOP}px`;
    Object.assign(mapEl.style, { width: `${mapW}px`, height: `${mapH}px` });
    svg.setAttribute("width", mapW);
    svg.setAttribute("height", mapH);
    drawBaseEdges();
    drawFocus();
    if (keep) panTo(keep.x, keep.y, 0, 0, false);
  }

  const pos = (id) => {
    const s = SK.get(id);
    return { x: s.x, y: laneTop.get(s.lane) + LANE_HEAD + s.y };
  };
  const visible = (id) => !state.collapsed.has(SK.get(id).lane);
  // Prerequisite q → skill s. Left-to-right when q is in an earlier column, otherwise loop around.
  function edgePath(q, s) {
    const a = pos(q);
    const b = pos(s);
    const ay = a.y + CH / 2;
    const by = b.y + CH / 2;
    if (a.x + CW < b.x) {
      const sx = a.x + CW;
      const tx = b.x - 2;
      const dx = Math.max(40, (tx - sx) / 2);
      return `M${sx},${ay} C${sx + dx},${ay} ${tx - dx},${by} ${tx},${by}`;
    }
    const sx = a.x;
    const tx = b.x + CW + 2;
    return `M${sx},${ay} C${sx - 70},${ay} ${tx + 70},${by} ${tx},${by}`;
  }
  const pathEl = (d, cls, marker) => {
    const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
    p.setAttribute("d", d);
    p.setAttribute("class", cls);
    if (marker) p.setAttribute("marker-end", `url(#${marker})`);
    return p;
  };

  function drawBaseEdges() {
    gBase.replaceChildren();
    for (const s of D.skills) {
      for (const r of s.required) {
        if (!visible(s.id) || !visible(r.id) || SK.get(r.id).lane !== s.lane) continue;
        const p = pathEl(edgePath(r.id, s.id), "e-base");
        p.dataset.from = r.id;
        p.dataset.to = s.id;
        gBase.append(p);
      }
    }
  }

  // ── focus (selection) ─────────────────────────────────────────────
  let chain = new Set();
  function drawFocus() {
    gFocus.replaceChildren();
    chain = new Set();
    const planIds = new Set(state.goal.length ? planFor(state.goal) : []);
    if (selected) {
      const s = SK.get(selected);
      const anc = ancestors(selected);
      chain = new Set([selected, ...anc, ...s.recommended.map((r) => r.id), ...s.unlocks]);
      const draw = (q, t, cls, marker) => { if (visible(q) && visible(t)) gFocus.append(pathEl(edgePath(q, t), cls, marker)); };
      for (const id of [selected, ...anc]) for (const r of SK.get(id).required) draw(r.id, id, "e-req", "arr-req");
      for (const r of s.recommended) draw(r.id, selected, "e-rec", "arr-rec");
      for (const d of s.unlocks) draw(selected, d, "e-out", "arr-out");
    }
    const focusSet = selected ? chain : planIds.size ? planIds : null;
    for (const p of gBase.children) {
      const lit = state.learned.has(p.dataset.from) && state.learned.has(p.dataset.to);
      p.classList.toggle("lit", lit);
      p.classList.toggle("dim", !!focusSet && !(focusSet.has(p.dataset.from) && focusSet.has(p.dataset.to)));
    }
    const order = [...planIds].filter((id) => !state.learned.has(id));
    for (const [id, c] of cards) {
      c.classList.toggle("sel", id === selected);
      c.classList.toggle("dim", !!focusSet && !focusSet.has(id));
      c.querySelector(".plan-no")?.remove();
      const n = order.indexOf(id);
      if (n >= 0) c.append(el("span", { class: "plan-no", "aria-hidden": "true" }, String(n + 1)));
    }
  }

  // ── status refresh ────────────────────────────────────────────────
  function refresh() {
    let avail = 0;
    for (const [id, c] of cards) {
      const st = status(id);
      if (st === "avail") avail++;
      c.classList.remove("lit", "avail", "locked");
      c.classList.add(st);
      c.querySelector(".c-ico").innerHTML = ICON[st];
      const s = SK.get(id);
      const missing = s.required.filter((r) => !state.learned.has(r.id)).length;
      c.setAttribute("aria-label", `${s.name}，第 ${s.step} 步，${STATE_TEXT[st]}${st === "locked" ? `，还差 ${missing} 个必须前置` : ""}`);
    }
    for (const lane of D.lanes) {
      const members = D.skills.filter((s) => s.lane === lane.id);
      laneEls.get(lane.id)._prog.textContent = `${members.filter((s) => state.learned.has(s.id)).length} / ${members.length}`;
    }
    const total = D.skills.length;
    $("#lit-count").textContent = state.learned.size;
    $("#total-count").textContent = total;
    $("#avail-count").textContent = avail;
    $("#bar-fill").style.width = `${(100 * state.learned.size) / total}%`;
    renderNext();
    renderPlan();
    drawFocus();
    if (selected) renderPanel(selected);
    Overview.render();
  }

  // ── side: next + plan ─────────────────────────────────────────────
  let showAllNext = false;
  function itemButton(id, extra, showStep) {
    const s = SK.get(id);
    const st = status(id);
    return el("button", { onclick: () => { openSkill(id); closeSideOnNarrow(); } },
      el("span", { class: `st-ico ${st}`, html: ICON[st], title: STATE_TEXT[st] }),
      el("span", {}, el("span", { class: "it-name" }, s.name), el("span", { class: "it-sub" }, showStep ? `第 ${s.step} 步 · ` : "", el("span", { lang: "en" }, s.en))),
      extra);
  }
  function renderNext() {
    const list = D.skills.filter((s) => status(s.id) === "avail" && !(s.optional && state.collapsed.has(s.lane)))
      .sort((a, b) => b.reach - a.reach || a.step - b.step);
    $("#next-count").textContent = `(${list.length})`;
    const shown = showAllNext ? list : list.slice(0, 8);
    $("#next-list").replaceChildren(...shown.map((s) =>
      el("li", {}, itemButton(s.id, el("span", { class: "it-meta", title: "学完它，后面一共有这么多技能会用到它" }, s.reach ? `后续 ${s.reach}` : "")))));
    const more = $("#btn-next-more");
    more.hidden = list.length <= 8;
    more.textContent = showAllNext ? "收起" : `显示全部 ${list.length} 个`;
  }
  function renderPlan() {
    const box = $("#plan");
    if (!state.goal.length) { box.hidden = true; return; }
    box.hidden = false;
    const plan = planFor(state.goal);
    const todo = plan.filter((id) => !state.learned.has(id));
    $("#plan-title").textContent = state.goalLabel || "学习计划";
    $("#btn-plan-clear").textContent = state.goalLabel.startsWith("路线：") ? "退出路线" : "取消目标";
    $("#plan-note").textContent = todo.length
      ? `还要学 ${todo.length} 个技能（已完成 ${plan.length - todo.length}）。按编号顺序学，每个都只依赖前面的。`
      : "这条路线已经全部点亮了！";
    let n = 0;
    $("#plan-list").replaceChildren(...plan.map((id) => {
      const done = state.learned.has(id);
      return el("li", { class: done ? "done" : "" }, itemButton(id, el("span", { class: "it-no" }, done ? "✓" : String(++n)), true));
    }));
  }
  $("#btn-next-more").addEventListener("click", () => { showAllNext = !showAllNext; renderNext(); });
  $("#btn-plan-clear").addEventListener("click", () => setGoal([], ""));

  function setGoal(ids, label, routeIndex = "") {
    state.goal = ids;
    state.goalLabel = label;
    $("#route-select").value = String(routeIndex);
    save();
    refresh();
  }

  // ── learning actions ──────────────────────────────────────────────
  function learn(ids, message) {
    const before = new Set(state.learned);
    for (const id of ids) state.learned.add(id);
    save();
    const wasAvail = (s) => !before.has(s.id) && s.required.every((r) => before.has(r.id));
    const newlyAvail = D.skills.filter((s) => status(s.id) === "avail" && !wasAvail(s)).map((s) => s.name);
    refresh();
    const tail = newlyAvail.length ? `，解锁了：${newlyAvail.slice(0, 4).join("、")}${newlyAvail.length > 4 ? ` 等 ${newlyAvail.length} 个` : ""}` : "";
    toast(message + tail, "撤销", () => { state.learned = before; save(); refresh(); });
  }
  function unlearn(ids, message) {
    const before = new Set(state.learned);
    for (const id of ids) state.learned.delete(id);
    save();
    refresh();
    toast(message, "撤销", () => { state.learned = before; save(); refresh(); });
  }
  function toggleLearn(id) {
    const st = status(id);
    if (st === "avail") learn([id], `已点亮「${SK.get(id).name}」`);
    else if (st === "lit") {
      const deps = [...dependents(id)].filter((d) => state.learned.has(d));
      if (deps.length) { renderPanel(id, { confirmUnlearn: deps }); return; }
      unlearn([id], `已取消「${SK.get(id).name}」`);
    } else toast(`「${SK.get(id).name}」还没解锁：先点亮它的必须前置`);
  }

  // ── detail panel ──────────────────────────────────────────────────
  const panel = $("#panel");
  const panelInner = $("#panel-inner");

  function prereqItem(r) {
    const s = SK.get(r.id);
    const st = status(r.id);
    return el("li", {}, el("button", { onclick: () => select(r.id) },
      el("span", { class: `st-ico ${st}`, html: ICON[st], title: STATE_TEXT[st] }),
      el("span", {},
        el("span", { class: "pr-name" }, s.name, el("span", { class: "pr-en", lang: "en" }, s.en)),
        r.why ? el("span", { class: "pr-why" }, r.why) : null)));
  }

  // Minimal formatter for exercise text: ``` fenced code, `inline code`, line breaks. Input is escaped first.
  function fmt(text) {
    const parts = String(text || "").split(/```(?:\w+)?\n?/);
    return parts.map((p, i) => i % 2
      ? `<pre tabindex="0"><code>${esc(p.replace(/\n$/, ""))}</code></pre>`
      : esc(p).replace(/`([^`]+)`/g, "<code>$1</code>").replace(/\n/g, "<br>")).join("");
  }

  function resourceCard(res, label) {
    if (!res) return null;
    const cost = res.free === true ? "免费" : res.free === false ? "付费 / 部分免费" : "访问条件见说明";
    return el("div", { class: "res" },
      el("h4", { class: "res-heading" }, label + (res.role === "reference" ? " · 查阅参考" : res.role === "alternative" ? " · 可选替代" : "")),
      el("span", { class: "res-tier" }, `${TIER_TEXT[res.tier] || res.tier} · ${cost}`),
      el("a", { href: res.url, target: "_blank", rel: "noopener noreferrer" }, res.title),
      res.access ? el("span", { class: "res-access" }, res.access) : null,
      res.covers || res.note ? el("details", { class: "res-details" },
        el("summary", {}, "学习范围与建议"),
        res.covers ? el("p", { class: "res-covers" }, res.covers) : null,
        res.note ? el("p", { class: "res-covers" }, res.note) : null) : null);
  }

  function learningPathSection(s) {
    const path = s.learningPath;
    if (!path) return el("p", { class: "route-summary route-pending" }, "中英文独立学习路线尚待逐知识点核对；以下是现有学习入口。");
    const sources = new Map(path.sources.map(r => [r.key, r]));
    const title = { zh: "中文", en: "英文" };
    const linked = (key, text) => {
      const r = sources.get(key);
      return el("a", { href: r.url, target: "_blank", rel: "noopener noreferrer", title: r.title }, text || r.title);
    };
    const box = el("div", { class: "learning-paths" },
      el("p", { class: "route-summary" }, ["zh", "en"].map(lang => `${title[lang]} ${path.routes[lang].covered}/${path.routes[lang].total}`).join(" · ") + " 个必学知识点有对应教学内容"));
    for (const lang of ["zh", "en"]) {
      const route = path.routes[lang];
      const text = (route.status === "complete" ? `覆盖 ${route.total}/${route.total}` : `待补 ${route.gaps.length} 项`) + ` · 免费已核 ${route.freeCovered}/${route.total}`;
      box.append(el("details", { class: "learning-route", open: lang === "zh" },
        el("summary", {}, `${title[lang]}独立学习路线 · ${text}`),
        el("ol", {}, (seen => route.steps.map(step => {
          const r = sources.get(step.source);
          const cost = r.free === true ? "免费" : r.free === false ? "付费 / 部分免费" : "访问条件见说明";
          // A material used in several steps shows its cost and access note once, at its first step.
          const first = !seen.has(step.source);
          seen.add(step.source);
          return el("li", {}, linked(step.source), first ? el("span", { class: "route-cost" }, cost) : null,
            el("p", {}, step.read), first ? el("p", { class: "route-access" }, r.access) : null);
        }))(new Set())),
        route.paidTopics.length ? el("p", { class: "route-gap" }, `当前需付费补读：${route.paidTopics.join("、")}`) : null,
        route.accessPendingTopics.length ? el("p", { class: "route-gap" }, `费用或回放条件待核：${route.accessPendingTopics.join("、")}`) : null,
        route.gaps.length ? el("p", { class: "route-gap" }, `尚待补齐：${route.gaps.join("、")}`) : null));
    }
    const table = el("table", { class: "coverage-table" },
      el("thead", {}, el("tr", {}, el("th", { scope: "col" }, "知识点"), el("th", { scope: "col" }, "中文章节"), el("th", { scope: "col" }, "英文章节"))),
      el("tbody", {}, path.topics.map(topic => el("tr", {},
        el("th", { scope: "row" }, topic.topic, topic.stage === "extension" ? el("span", { class: "route-access" }, "选读延伸") : null,
          topic.stage === "extension" && topic.note ? el("span", { class: "route-access" }, topic.note) : null),
        ...["zh", "en"].map(lang => el("td", {},
          topic[lang]?.length ? topic[lang].map(ref => el("div", {}, linked(ref.source, (ref.extent === "partial" ? "部分：" : "") + ref.section))) : "待补"))))));
    box.append(el("details", { class: "coverage-details" }, el("summary", {}, "逐知识点查看对应章节"), table));
    for (const f of path.crossLanguageFallbacks) box.append(el("p", { class: "route-gap" },
      `${title[f.lang_missing]}「${f.topic}」的跨语言补充：`, linked(f.source), `。${f.reason}`));
    return box;
  }

  function renderPanel(id, opts = {}) {
    const s = SK.get(id);
    const st = status(id);
    const missing = s.required.filter((r) => !state.learned.has(r.id));
    const isGoal = state.goal.length === 1 && state.goal[0] === id;
    const kids = [];

    kids.push(el("button", { class: "icon-btn p-close", "aria-label": "关闭详情", onclick: () => select(null) }, "×"));
    kids.push(el("div", {},
      el("div", { class: "p-crumb" }, s.path.map((p) => p.name).join(" › ")),
      el("h2", { class: "p-title" }, s.name),
      el("div", { class: "p-en", lang: "en" }, s.en),
      el("div", { class: "chips" },
        el("span", { class: "chip", title: "前面至少有这么多层必须前置" }, `第 ${s.step} 步`),
        el("span", { class: "chip", title: D.depths[s.entry]?.goal }, `入门层 D${s.entry} ${D.depths[s.entry]?.name || ""}`),
        el("span", { class: "chip" }, `深度 ${s.levels.map((l) => "D" + l).join(" ")}`),
        s.optional ? el("span", { class: "chip", title: s.scope }, "选修") : null,
        s.prereqStatus === "verified"
          ? el("span", { class: "chip ok", title: "必须/推荐前置已用真实课程的先修要求核实" }, "前置已核实")
          : el("span", { class: "chip warn", title: "按常见课程体系起草，还在找真实课程证据" }, "前置待核实")),
      s.optional ? el("p", { class: "p-scope" }, s.scope) : null));

    // status + primary action
    const box = el("div", { class: `status-box ${st}` });
    if (opts.confirmUnlearn) {
      const names = opts.confirmUnlearn.map((d) => SK.get(d).name);
      box.append(el("div", { class: "confirm" },
        `取消「${s.name}」后，这 ${names.length} 个已点亮的技能会失去必须前置：${names.join("、")}。要一起取消吗？`));
      box.append(el("div", { class: "status-actions" },
        el("button", { class: "btn primary", onclick: () => unlearn([id, ...opts.confirmUnlearn], `已取消「${s.name}」及 ${names.length} 个后续技能`) }, "一起取消"),
        el("button", { class: "btn", onclick: () => renderPanel(id) }, "都不取消")));
    } else if (st === "lit") {
      box.append(el("div", { class: "status-line" }, el("span", { class: "st-ico lit", html: ICON.lit }), "已点亮"));
      box.append(el("div", { class: "status-actions" }, el("button", { class: "btn", onclick: () => toggleLearn(id) }, "取消点亮")));
    } else if (st === "avail") {
      box.append(el("div", { class: "status-line" }, el("span", { class: "st-ico avail", html: ICON.avail }),
        s.required.length ? "必须前置都已点亮，可以学了" : "没有必须前置，现在就能学"));
      box.append(el("div", { class: "status-actions" },
        el("button", { class: "btn primary", onclick: () => toggleLearn(id) }, "学会了，点亮")));
    } else {
      const chainTodo = [...ancestors(id)].filter((a) => !state.learned.has(a));
      box.append(el("div", { class: "status-line" }, el("span", { class: "st-ico locked", html: ICON.locked }),
        `未解锁：还差 ${missing.length} 个必须前置`));
      box.append(el("div", { class: "confirm" }, `先点亮：${missing.map((r) => SK.get(r.id).name).join("、")}。`));
      box.append(el("div", { class: "status-actions" },
        el("button", { class: "btn primary", disabled: true, title: "必须前置都点亮后才能点亮" }, "点亮"),
        isGoal
          ? el("button", { class: "btn", onclick: () => setGoal([], "") }, "取消目标")
          : el("button", { class: "btn", onclick: () => setGoal([id], `目标：${s.name}`) }, "设为目标，排出学习顺序"),
        el("button", { class: "btn small", title: "如果这些前置你其实已经学过", onclick: () => learn([...chainTodo, id], `已点亮「${s.name}」和它的 ${chainTodo.length} 个前置`) },
          `我都会：连同 ${chainTodo.length} 个前置一起点亮`)));
    }
    if (st !== "locked" && !opts.confirmUnlearn) {
      box.lastChild.append(isGoal
        ? el("button", { class: "btn small", onclick: () => setGoal([], "") }, "取消目标")
        : el("button", { class: "btn small", onclick: () => setGoal([id], `目标：${s.name}`) }, "设为目标"));
    }
    kids.push(box);

    // prerequisites
    kids.push(el("section", { class: "p-sec" },
      el("h3", {}, "必须前置", el("span", { class: "h-note" }, "全部点亮后才能点亮本技能")),
      s.required.length ? el("ul", { class: "pr-list" }, s.required.map(prereqItem)) : el("p", { class: "pr-empty" }, "没有必须前置。"),
      s.prereqSummary ? el("p", { class: "pr-empty" }, s.prereqSummary) : null));
    if (s.recommended.length) {
      kids.push(el("section", { class: "p-sec" },
        el("h3", {}, "推荐前置", el("span", { class: "h-note" }, "建议先学，不挡路")),
        el("ul", { class: "pr-list" }, s.recommended.map(prereqItem))));
    }
    if (s.unlocks.length) {
      kids.push(el("section", { class: "p-sec" },
        el("h3", {}, "学完能解锁", el("span", { class: "h-note" }, `直接 ${s.unlocks.length} 个，后续一共 ${s.reach} 个`)),
        el("ul", { class: "pr-list" }, s.unlocks.slice().sort(byStep).map((d) => prereqItem({ id: d })))));
    }

    // content
    const ms = s.milestones ? Object.entries(s.milestones) : [];
    kids.push(el("section", { class: "p-sec" },
      el("h3", {}, "学什么"),
      el("p", {}, s.desc),
      s.granularity ? el("details", {},
        el("summary", {}, `划分依据（${s.granularity.unit}）`),
        el("p", {}, s.granularity.boundary || s.granularity.note || s.granularity.evidence),
        el("a", { href: s.granularity.url, target: "_blank", rel: "noopener noreferrer" }, s.granularity.source_title)) : null,
      ms.length ? el("ul", { class: "milestones" }, ms.map(([lv, g]) => el("li", {}, el("b", {}, `D${lv}：`), g))) : null));
    kids.push(Guide.section(s));

    // Learning resources share the same presentation so Chinese materials are easy to find.
    kids.push(el("section", { class: "p-sec learning-resources" },
      el("h3", {}, "去哪学"),
      learningPathSection(s),
      el("div", { class: "res-list" },
        resourceCard(s.resource, s.resource?.lang === "zh" ? "中文资源" : "英文资源"),
        resourceCard(s.zhAlt, "中文资源")),
      s.extraResources?.length ? el("details", { class: "extra-resources" },
        el("summary", {}, "补充材料（填补主资源的覆盖缺口）"),
        el("div", { class: "res-list" }, s.extraResources.map(r => resourceCard(r, r.lang === "zh" ? "中文补充" : r.lang === "en" ? "英文补充" : "补充（语言见说明）")))) : null,
      !s.resource && !s.zhAlt ? el("p", { class: "pending" }, "暂无核实过的学习资源。") : null,
      !s.zhAlt && s.resource?.lang !== "zh" ? el("p", { class: "pending" }, s.zhResourceNote || "暂未找到并核实适合本节点的中文资源。") : null));

    // exercise
    const ex = s.exercise;
    kids.push(el("section", { class: "p-sec" },
      el("h3", {}, "练习题", el("span", { class: "h-note" }, `按入门层 D${s.entry} 出，只用本技能和它的前置`)),
      ex ? el("div", { class: "ex" },
        el("div", { class: "ex-meta" }, `约 ${ex.time_min || 40} 分钟${ex.covers?.length ? " · 覆盖：" + ex.covers.join("、") : ""}`),
        el("div", { html: fmt(ex.question) }),
        el("details", {}, el("summary", {}, "看参考答案"), el("div", { class: "ex-answer", html: fmt(ex.answer) })))
        : el("p", { class: "pending" }, "这个技能暂时没有配练习题。")));

    // evidence
    if (s.courses.length) {
      kids.push(el("section", { class: "p-sec courses" },
        el("details", {}, el("summary", {}, `前置依据：${s.courses.length} 条课程资料`),
          el("ul", {}, s.courses.map((c) => el("li", {},
            el("a", { href: c.url, target: "_blank", rel: "noopener" }, `${c.school} ${c.course}`), "：",
            el("q", {}, c.prereq_text || "未写明先修")))))));
    }
    if (s.requiredEvidence?.length) {
      const basis = { course: "课程背景", same_course: "同课顺序", chain: "先修链" };
      const entries = s.requiredEvidence.map(e => {
        const sources = e.sources.map((x, i) => el("p", {},
          el("q", {}, x.quote), " ",
          el("a", { href: x.url, target: "_blank", rel: "noopener noreferrer" }, `查看官方原文 ${i + 1}`)));
        return el("li", {},
          el("strong", {}, `${SK.get(e.id)?.name || e.id} · ${basis[e.basis]}`),
          el("p", {}, e.reason), e.limits ? el("p", {}, e.limits) : null, sources);
      });
      kids.push(el("section", { class: "p-sec" },
        el("details", {}, el("summary", {}, "必须前置的补充证据"), el("ul", {}, entries))));
    }
    if (s.related.length) {
      kids.push(el("section", { class: "p-sec" },
        el("h3", {}, "相关但不是前置"),
        el("p", { class: "pr-empty" }, s.related.map((r) => SK.get(r.id).name).join("、"))));
    }

    panelInner.replaceChildren(...kids);
    panel.hidden = false;
  }

  function select(id) {
    selected = id;
    if (id) { renderPanel(id); panel.scrollTop = 0; } else panel.hidden = true;
    drawFocus();
    if (id) ensureVisible(id);
    if (view === "map") history.replaceState(null, "", id ? `#skill/${id}` : "#map");
  }

  // ── pan / zoom ────────────────────────────────────────────────────
  const wrap = $("#map-wrap");
  // Panzoom's wheel-zoom focal math assumes the default transform-origin (50% 50%) for HTML elements, so the
  // helpers below convert between map coordinates and wrap-local screen coordinates with that origin:
  //   screen = c + (p + t − c)·s,  c = map centre, t = pan, s = scale
  var pz = Panzoom(mapEl, { maxScale: 2, minScale: 0.15, step: 0.25, canvas: true, cursor: "" });
  function screenOf(px, py) {
    const s = pz.getScale();
    const t = pz.getPan();
    return { x: mapW / 2 + (px + t.x - mapW / 2) * s, y: mapH / 2 + (py + t.y - mapH / 2) * s };
  }
  function panTo(sx, sy, px, py, animate) {
    const s = pz.getScale();
    pz.pan((sx - mapW / 2) / s + mapW / 2 - px, (sy - mapH / 2) / s + mapH / 2 - py, { animate, force: true });
  }
  wrap.addEventListener("wheel", (e) => { e.preventDefault(); pz.zoomWithWheel(e); }, { passive: false });
  // Focusing an off-screen card (Tab) makes the browser scroll this overflow:hidden box, which shifts the
  // zoom buttons and breaks the pan maths. Undo it; the card's focus handler pans instead.
  wrap.addEventListener("scroll", () => { wrap.scrollTop = 0; wrap.scrollLeft = 0; });
  let dragMoved = false;
  let downAt = null;
  wrap.addEventListener("pointerdown", (e) => { downAt = [e.clientX, e.clientY]; dragMoved = false; }, true);
  wrap.addEventListener("pointermove", (e) => {
    if (downAt && Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 5) dragMoved = true;
  }, true);
  wrap.addEventListener("pointerup", () => { downAt = null; }, true);
  wrap.addEventListener("click", () => { if (!dragMoved && selected) select(null); });

  // fit(): every step column in view (button / key 0). fit(false), used when entering the map, keeps cards
  // readable (scale >= 0.8) and lets a wide map pan instead.
  function fit(all = true) {
    const r = wrap.getBoundingClientRect();
    const toWidth = Math.min(1, (r.width - 40) / (mapW + 40));
    // phones: stay readable and show the first columns instead of shrinking the whole width
    const scale = narrow() ? 0.62 : Math.max(all ? 0.3 : 0.8, toWidth);
    pz.zoom(scale, { animate: false, force: true });
    panTo(30, 10, 0, 0, false);
  }
  function ensureVisible(id) {
    const c = cards.get(id);
    if (!c || c.hidden) return;
    const r = wrap.getBoundingClientRect();
    const cr = c.getBoundingClientRect();
    const pad = 40;
    if (cr.left >= r.left + pad && cr.right <= r.right - pad && cr.top >= r.top + pad && cr.bottom <= r.bottom - pad) return;
    const p = pos(id);
    panTo(r.width / 2, r.height / 2, p.x + CW / 2, p.y + CH / 2, true);
  }
  $("#btn-fit").addEventListener("click", () => (view === "map" ? fit() : Overview.fit()));
  $("#btn-zoom-in").addEventListener("click", () => pz.zoomIn());
  $("#btn-zoom-out").addEventListener("click", () => pz.zoomOut());
  // Show one lane from its top at the fit-to-width scale, and flash it so the eye lands on it.
  function focusLaneInMap(laneId) {
    if (state.collapsed.has(laneId)) toggleLane(laneId);
    fit(false);
    panTo(30, 14, 0, laneTop.get(laneId), false);
    const box = laneEls.get(laneId);
    box.classList.remove("flash");
    void box.offsetWidth; // restart the animation
    box.classList.add("flash");
  }

  // ── views: overview ⇄ map, mirrored in the URL hash so Back / links work ──
  // #overview · #map · #map/<lane> · #skill/<id> · #skill/<id>/guide (knowledge map open)
  const layoutEl = $("#layout");
  const ovWrap = $("#ov-wrap");
  let view = "";
  let mapFitted = false;
  function showView(v) {
    if (v === view) return;
    view = v;
    layoutEl.dataset.view = v;
    ovWrap.hidden = v !== "overview";
    wrap.hidden = v !== "map";
    $("#tab-overview").setAttribute("aria-pressed", String(v === "overview"));
    $("#tab-map").setAttribute("aria-pressed", String(v === "map"));
    if (v === "overview") { panel.hidden = true; Overview.show(); return; }
    if (selected) panel.hidden = false;
    if (!mapFitted) { mapFitted = true; fit(false); }
  }
  function route() {
    const [v, arg, sub] = decodeURIComponent(location.hash.slice(1)).split("/");
    const alias = v === "skill" && D.progressMerges?.[arg];
    if (alias) {
      history.replaceState(null, "", `#skill/${alias}${sub ? "/" + sub : ""}`);
      return route();
    }
    if (v === "skill" && SK.has(arg)) {
      showView("map");
      if (state.collapsed.has(SK.get(arg).lane)) toggleLane(SK.get(arg).lane);
      select(arg);
      if (sub === "guide") Guide.open(arg);
    } else if (v === "map") {
      showView("map");
      if (LANE.has(arg)) { mapFitted = true; focusLaneInMap(arg); }
    } else showView("overview");
  }
  const go = (hash) => { if (location.hash === hash) route(); else location.hash = hash; };
  const openSkill = (id) => (view === "map" ? select(id) : go(`#skill/${id}`));
  window.addEventListener("hashchange", route);
  $("#tab-overview").addEventListener("click", () => go("#overview"));
  $("#tab-map").addEventListener("click", () => go(selected ? `#skill/${selected}` : "#map"));
  const Overview = window.SkillTreeOverview;
  const Guide = window.SkillTreeGuide;
  $("#skip-link").addEventListener("click", () => {
    const target = view === "overview"
      ? document.querySelector(".region .rg-main")
      : (selected && cards.get(selected)) || [...cards.values()].find((c) => !c.hidden && c.classList.contains("avail"));
    target?.focus();
  });

  // ── search ────────────────────────────────────────────────────────
  const input = $("#search-input");
  const results = $("#search-results");
  let hits = [];
  let hitIdx = 0;
  function runSearch() {
    const q = input.value.trim().toLowerCase();
    for (const c of cards.values()) c.classList.remove("match");
    if (!q) { closeResults(); return; }
    hits = D.skills.filter((s) => [s.name, s.en, s.id, s.desc].some((t) => t.toLowerCase().includes(q)))
      .sort((a, b) => (b.name.toLowerCase().includes(q) || b.en.toLowerCase().includes(q)) - (a.name.toLowerCase().includes(q) || a.en.toLowerCase().includes(q)))
      .slice(0, 10);
    hitIdx = 0;
    for (const s of hits) cards.get(s.id).classList.add("match");
    results.replaceChildren(...(hits.length ? hits.map((s, i) => el("li", {
      role: "option", id: `sr-${i}`, "aria-selected": String(i === hitIdx),
      onmousedown: (e) => { e.preventDefault(); pick(s.id); },
    }, el("span", {}, s.name), el("span", { class: "r-en", lang: "en" }, s.en), el("span", { class: "r-state" }, STATE_TEXT[status(s.id)])))
      : [el("li", { role: "option", "aria-disabled": "true" }, "没有找到")]));
    results.hidden = false;
    input.setAttribute("aria-expanded", "true");
    if (hits.length) input.setAttribute("aria-activedescendant", "sr-0"); else input.removeAttribute("aria-activedescendant");
  }
  function closeResults() {
    results.hidden = true;
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-activedescendant");
  }
  function pick(id) {
    closeResults();
    input.blur();
    for (const c of cards.values()) c.classList.remove("match");
    if (state.collapsed.has(SK.get(id).lane)) toggleLane(SK.get(id).lane);
    openSkill(id);
  }
  input.addEventListener("input", runSearch);
  input.addEventListener("keydown", (e) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      hitIdx = (hitIdx + (e.key === "ArrowDown" ? 1 : -1) + hits.length) % hits.length;
      [...results.children].forEach((li, i) => li.setAttribute("aria-selected", String(i === hitIdx)));
      input.setAttribute("aria-activedescendant", `sr-${hitIdx}`);
    } else if (e.key === "Enter" && hits[hitIdx]) pick(hits[hitIdx].id);
    else if (e.key === "Escape") { input.value = ""; runSearch(); input.blur(); }
  });
  input.addEventListener("blur", () => setTimeout(closeResults, 100));

  // ── routes ────────────────────────────────────────────────────────
  const routeSel = $("#route-select");
  D.routes.forEach((r, i) => routeSel.append(el("option", { value: String(i), title: r.note }, r.name)));
  routeSel.addEventListener("change", () => {
    const r = D.routes[Number(routeSel.value)];
    if (!r) { setGoal([], ""); return; }
    for (const id of r.ids) state.collapsed.delete(SK.get(id).lane);
    layout();
    setGoal(r.ids, `路线：${r.name}`, routeSel.value);
    $("#plan-note").textContent += ` ${r.note}`;
    openSideOnNarrow();
  });

  // ── menu, import / export, help ───────────────────────────────────
  const menuBtn = $("#btn-menu");
  const menuPop = $("#menu-pop");
  menuBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    menuPop.hidden = !menuPop.hidden;
    menuBtn.setAttribute("aria-expanded", String(!menuPop.hidden));
  });
  document.addEventListener("click", (e) => { if (!menuPop.contains(e.target)) menuPop.hidden = true; });
  $("#btn-export").addEventListener("click", () => {
    const blob = new Blob([JSON.stringify({ app: "cs-math-skilltree", version: 2, legacyProgress: state.legacyProgress, learned: [...state.learned], goal: state.goal, goalLabel: state.goalLabel }, null, 1)], { type: "application/json" });
    const a = el("a", { href: URL.createObjectURL(blob), download: `skilltree-progress-${new Date().toISOString().slice(0, 10)}.json` });
    document.body.append(a);
    a.click();
    a.remove();
    menuPop.hidden = true;
  });
  $("#file-import").addEventListener("change", async (e) => {
    const f = e.target.files[0];
    if (!f) return;
    try {
      const data = JSON.parse(await f.text());
      const before = new Set(state.learned);
      for (const id of readProgress(data)) state.learned.add(id);
      if (!state.legacyProgress && (data.version || 1) < 2) state.legacyProgress = { learned: data.learned || [], goal: data.goal || [] };
      normalizeLearned();
      save();
      refresh();
      toast(`已导入，合并后共点亮 ${state.learned.size} 个`, "撤销", () => { state.learned = before; save(); refresh(); });
    } catch { toast("导入失败：文件不是有效的进度 JSON"); }
    e.target.value = "";
    menuPop.hidden = true;
  });
  let resetArmed = false;
  $("#btn-reset").addEventListener("click", (e) => {
    e.stopPropagation();
    if (!resetArmed) { resetArmed = true; e.target.textContent = "再点一次确认清空"; return; }
    resetArmed = false;
    e.target.textContent = "清空进度";
    menuPop.hidden = true;
    unlearn([...state.learned], "已清空全部进度");
  });
  $("#btn-help").addEventListener("click", () => $("#help-dialog").showModal());

  // ── intro, narrow-screen side panel ───────────────────────────────
  const intro = $("#intro");
  intro.hidden = state.introSeen;
  $("#btn-intro-ok").addEventListener("click", () => { state.introSeen = true; intro.hidden = true; save(); });
  const side = $("#side");
  const sideBtn = $("#btn-side");
  const narrow = () => window.matchMedia("(max-width: 900px)").matches;
  sideBtn.addEventListener("click", () => {
    side.classList.toggle("open");
    sideBtn.setAttribute("aria-expanded", String(side.classList.contains("open")));
  });
  function closeSideOnNarrow() { if (narrow()) { side.classList.remove("open"); sideBtn.setAttribute("aria-expanded", "false"); } }
  function openSideOnNarrow() { if (narrow()) { side.classList.add("open"); sideBtn.setAttribute("aria-expanded", "true"); } }

  // ── toast ─────────────────────────────────────────────────────────
  const toastEl = $("#toast");
  const toastAct = $("#toast-action");
  let toastTimer = null;
  function toast(msg, actionText, action) {
    $("#toast-msg").textContent = msg;
    toastAct.hidden = !actionText;
    toastAct.textContent = actionText || "";
    toastAct.onclick = () => { toastEl.hidden = true; action?.(); };
    toastEl.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { toastEl.hidden = true; }, 6000);
  }

  // ── keyboard ──────────────────────────────────────────────────────
  document.addEventListener("keydown", (e) => {
    const typing = /INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName);
    if (document.querySelector("dialog[open]")) return;
    if (e.key === "/" && !typing) { e.preventDefault(); input.focus(); return; }
    if (typing || e.ctrlKey || e.metaKey || e.altKey) return;
    if (view === "overview") {
      if (e.key === "0") Overview.fit();
      else if (e.key === "+" || e.key === "=") Overview.zoomIn();
      else if (e.key === "-") Overview.zoomOut();
      return;
    }
    if (e.key === "Escape") { if (selected) select(null); else go("#overview"); }
    else if ((e.key === "l" || e.key === "L") && selected) toggleLearn(selected);
    else if ((e.key === "g" || e.key === "G") && selected) Guide.open(selected);
    else if (e.key === "0") fit();
    else if (e.key === "+" || e.key === "=") pz.zoomIn();
    else if (e.key === "-") pz.zoomOut();
  });

  // ── go ────────────────────────────────────────────────────────────
  Overview.init({
    data: D,
    status,
    icon: (st) => ICON[st],
    planIds: () => (state.goal.length ? planFor(state.goal) : []),
    laneProgress: (laneId) => {
      const m = D.skills.filter((s) => s.lane === laneId);
      return m.filter((s) => state.learned.has(s.id)).length / m.length;
    },
    enterLane: (laneId) => go(`#map/${laneId}`),
    pickSkill: (id) => go(`#skill/${id}`),
  });
  Guide.init({
    skill: (id) => SK.get(id),
    color: (id) => LANE.get(SK.get(id).lane).color,
    onOpen: (id) => history.replaceState(null, "", `#skill/${id}/guide`),
    onClose: (id) => { if (view === "map" && selected === id) history.replaceState(null, "", `#skill/${id}`); },
  });
  layout();
  refresh();
  if (state.goal.length) {
    const i = D.routes.findIndex((r) => `路线：${r.name}` === state.goalLabel);
    if (i >= 0) routeSel.value = String(i);
  }
  // Panzoom's constructor queues setTimeout(() => pan(startX, startY)); timers run in order, so routing from a
  // later timer keeps a deep link (#map/<lane>, #skill/<id>) from being reset to the origin.
  setTimeout(() => {
    route();
    if (progressRevised) {
      save();
      toast("部分技能已合并，扩展后的内容需重新确认。旧进度随导出保留。 ");
    }
  });
})();
